          <div class="pc-analyzing-progress" role="progressbar" aria-label="Claude analysis progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0">
            <span class="pc-analyzing-progress-fill" aria-hidden="true"></span>
          </div>
